#!/bin/sh
set -eu
historical_sha=86e867c2a64267a674ce4fbf6a3064af39e2f4e0
usage(){ echo "usage: $0 --repository DIR --build-dir NEW_DIR --case batch_alpha|heat_sn160 --records DIR [--repetitions N]" >&2; exit 2; }
repository= build_dir= case= records= repetitions=5
while [ "$#" -gt 0 ]; do case "$1" in --repository|--build-dir|--case|--records|--repetitions) [ "$#" -ge 2 ] || usage; case "$1" in --repository) repository=$2;; --build-dir) build_dir=$2;; --case) case=$2;; --records) records=$2;; --repetitions) repetitions=$2;; esac; shift 2;; *) usage;; esac; done
[ -n "$repository" ] && [ -n "$build_dir" ] && [ -n "$case" ] && [ -n "$records" ] || usage
case "$repetitions" in *[!0-9]*|'') usage;; esac; [ "$repetitions" -gt 0 ] || usage
repository=$(cd "$repository" && pwd -P); case "$build_dir" in /*);; *) build_dir=$PWD/$build_dir;; esac
[ ! -e "$build_dir" ] || { echo "build directory must not exist" >&2; exit 2; }
[ "$(git -C "$repository" rev-parse HEAD)" = "$historical_sha" ] && [ -z "$(git -C "$repository" status --porcelain)" ] || { echo "repository must be clean historical staging" >&2; exit 2; }
case "$case" in batch_alpha) settings=$repository/test/test_settings_batch; setup=$repository/test/Test_Problems/setup_batch_alpha; network=Data_alpha; trajectories=th_batch; expected=16;; heat_sn160) settings=$repository/test/test_settings_heat; setup=$repository/test/Test_Problems/setup_heat_sn160; network=Data_SN160; trajectories=co_burn; expected=6;; *) echo "case is not ready direct serial" >&2; exit 2;; esac
mkdir -p "$records"; record=$records/${case}-$(date -u +%Y%m%dT%H%M%SZ)-$$; mkdir "$record" "$record/repetitions"
if ! make -C "$repository" BUILD_DIR="$build_dir" xnet > "$record/build.log" 2>&1; then echo "fresh build failed" >&2; exit 1; fi
executable=$build_dir/bin/xnet; config=$build_dir/config.txt; [ -x "$executable" ] && [ -f "$config" ] || exit 1
cfg(){ awk -F= -v key="$1" '$1==key {print $2}' "$config"; }
[ "$(cfg SOURCE_ROOT)" = "$repository" ] || exit 1
for key in MPI_MODE OPENMP_MODE GPU_MODE OPENACC_MODE OPENMP_OL_MODE; do [ "$(cfg "$key")" = OFF ] || { echo "direct serial rejects $key" >&2; exit 1; }; done
[ "$(cfg MATRIX_SOLVER)" = dense ] || { echo "direct serial requires dense" >&2; exit 1; }
hash(){ if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1"; else shasum -a 256 "$1"; fi; }
tracked(){ git -C "$repository" ls-files -- "$1" | while IFS= read -r f; do hash "$repository/$f"; done; }
{ printf 'sha256\tpath\n'; hash "$settings"|awk '{print $1"\t"$2}'; hash "$setup"|awk '{print $1"\t"$2}'; tracked "test/$network"|awk '{print $1"\t"$2}'; if [ "$trajectories" = th_batch ]; then tracked test/Test_Problems/th_batch|awk '{print $1"\t"$2}'; else git -C "$repository" ls-files -- test/Test_Problems|grep '/th_co_burn_'|while IFS= read -r f; do hash "$repository/$f"|awk '{print $1"\t"$2}'; done; fi; hash "$repository/tools/starkiller-helmholtz/helm_table.dat"|awk '{print $1"\t"$2}'; } > "$record/input.sha256"
{ printf 'schema\txnet-v9-benchmark-record-v2\nhistorical_source_sha\t%s\nsource_sha\t%s\nsource_root\t%s\ncase_id\t%s\nexecution_mode\tdirect-serial\nlauncher\tnone\n' "$historical_sha" "$historical_sha" "$repository" "$case"; printf 'build_config_path\t%s\nbuild_config_sha256\t%s\nexecutable_path\t%s\nexecutable_sha256\t%s\nexpected_end_records\t%s\nrepetitions_requested\t%s\ncaptured_utc\t%s\nhost\t%s\nuname\t%s\n' "$config" "$(hash "$config"|awk '{print $1}')" "$executable" "$(hash "$executable"|awk '{print $1}')" "$expected" "$repetitions" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$(hostname)" "$(uname -a)"; } > "$record/metadata.tsv"
printf 'repetition\texit_status\tend_records\ttimer_setup_seconds\ttimer_total_seconds\tnumerical_success\n' > "$record/repetitions.tsv"
rep=1; while [ "$rep" -le "$repetitions" ]; do work=$(mktemp -d "${TMPDIR:-/tmp}/xnet-benchmark.XXXXXX"); trap 'rm -rf "$work"' EXIT HUP INT TERM; artifact=$record/repetitions/$rep; mkdir "$artifact" "$work/Test_Results" "$work/Test_Problems"; cat "$settings" "$setup" > "$work/control"; cp -R "$repository/test/$network" "$work/$network"; ln -s "$repository/tools/starkiller-helmholtz/helm_table.dat" "$work/helm_table.dat"; if [ "$trajectories" = th_batch ]; then ln -s "$repository/test/Test_Problems/th_batch" "$work/Test_Problems/th_batch"; else for f in "$repository"/test/Test_Problems/th_co_burn_*; do ln -s "$f" "$work/Test_Problems/$(basename "$f")"; done; fi; set +e; (cd "$work" && "$executable") > "$artifact/stdout.txt" 2> "$artifact/stderr.txt"; status=$?; set -e; cp "$work"/net_diag* "$artifact/" 2>/dev/null || true; ends=$(grep -h '^End[[:space:]]' "$artifact"/net_diag* 2>/dev/null|wc -l|tr -d ' '); setup_time=$(awk '$1=="Setup"{v=$2}END{print v+0}' "$artifact"/net_diag* 2>/dev/null||printf 0); total=$(awk '$1=="Total"{v=$2}END{print v+0}' "$artifact"/net_diag* 2>/dev/null||printf 0); success=no; if [ "$status" -eq 0 ] && [ "$ends" -eq "$expected" ] && awk -v v="$total" 'BEGIN{exit !(v>0)}'; then success=structural-pass; fi; printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$rep" "$status" "$ends" "$setup_time" "$total" "$success" >> "$record/repetitions.tsv"; rm -rf "$work"; trap - EXIT HUP INT TERM; rep=$((rep+1)); done
sh "$(dirname "$0")/validate.sh" "$record"; echo "$record"
